import unittest
from pricing import total_price

class PricingTests(unittest.TestCase):
    def test_total_price_uses_quantity(self):
        self.assertEqual(total_price([{"price": 4, "quantity": 3}, {"price": 2, "quantity": 2}]), 16)

if __name__ == "__main__":
    unittest.main()
